        var course = post.getCoursePostingBelongsTo();
        if (course == null) {
            throw new IllegalStateException("Course is null for post " + post.getId());
        }
        // The post can be located in a channel that is linked to an exercise. If so, we pass the exercise details to the pipeline.
        Long exerciseId = null;
        if (post.getConversation() instanceof Channel channel && channel.getExercise() != null) {
            exerciseId = channel.getExercise().getId();
        }
        final Long associatedExerciseId = exerciseId;
        // @formatter:off
        executePipeline(
            "tutor-suggestion",
            variant,
            eventVariant,
            pyrisJobService.addTutorSuggestionJob(post.getId(), course.getId(), session.getId()),
            executionDto -> {
                var user = userRepository.findByIdElseThrow(session.getUserId());
                Optional<PyrisTextExerciseDTO> textExerciseDTO = Optional.empty();
                Optional<PyrisProgrammingExerciseDTO> programmingExerciseDTO = Optional.empty();
                if (associatedExerciseId != null) {
                    Exercise exercise = exerciseRepository.findByIdElseThrow(associatedExerciseId);
                    if (exercise instanceof ProgrammingExercise) {
                        var programmingExercise = programmingExerciseRepository.findByIdWithTemplateAndSolutionParticipationElseThrow(associatedExerciseId);
                        programmingExerciseDTO = Optional.of(pyrisDTOService.toPyrisProgrammingExerciseDTO(programmingExercise));
                    }
                    else if (exercise instanceof TextExercise textExercise) {
                        textExerciseDTO = Optional.of(PyrisTextExerciseDTO.of(textExercise));
                    }
                }
                return new PyrisTutorSuggestionPipelineExecutionDTO(
                    new PyrisCourseDTO(course),
                    Optional.ofNullable(associatedExerciseId).map(Long::intValue),
                    new PyrisPostDTO(post),
                    pyrisDTOService.toPyrisMessageDTOList(session.getMessages()),
                    new PyrisUserDTO(user),
                    textExerciseDTO,
                    programmingExerciseDTO,
                    executionDto.settings(),
                    executionDto.initialStages()
                );
            },
            stages -> irisChatWebsocketService.sendStatusUpdate(session, stages)
        );
        // @formatter:on
    }", "originalFile": null, "structuredPatch": [{"oldStart": 260, "oldLines": 6, "newStart": 260, "newLines": 12, "lines": ["         if (course == null) {", "             throw new IllegalStateException("Course is null for post " + post.getId());", "         }", "+        // The post can be located in a channel that is linked to an exercise. If so, we pass the exercise details to the pipeline.", "+        Long exerciseId = null;", "+        if (post.getConversation() instanceof Channel channel && channel.getExercise() != null) {", "+            exerciseId = channel.getExercise().getId();", "+        }", "+        final Long associatedExerciseId = exerciseId;", "         // @formatter:off", "         executePipeline(", "             "tutor-suggestion","]}, {"oldStart": 268, "oldLines": 12, "newStart": 274, "newLines": 26, "lines": ["             pyrisJobService.addTutorSuggestionJob(post.getId(), course.getId(), session.getId()),", "             executionDto -> {", "                 var user = userRepository.findByIdElseThrow(session.getUserId());", "+                Optional<PyrisTextExerciseDTO> textExerciseDTO = Optional.empty();", "+                Optional<PyrisProgrammingExerciseDTO> programmingExerciseDTO = Optional.empty();", "+                if (associatedExerciseId != null) {", "+                    Exercise exercise = exerciseRepository.findByIdElseThrow(associatedExerciseId);", "+                    if (exercise instanceof ProgrammingExercise) {", "+                        var programmingExercise = programmingExerciseRepository.findByIdWithTemplateAndSolutionParticipationElseThrow(associatedExerciseId);", "+                        programmingExerciseDTO = Optional.of(pyrisDTOService.toPyrisProgrammingExerciseDTO(programmingExercise));", "+                    }", "+                    else if (exercise instanceof TextExercise textExercise) {", "+                        textExerciseDTO = Optional.of(PyrisTextExerciseDTO.of(textExercise));", "+          