247	     * Execute the tutor suggestion pipeline for the given session.
248	     * It provides specific data for the tutor suggestion pipeline, including:
249	     * - The post the session is about
250	     * - The messages of the session
251	     * - The user that created the session
252	     *
253	     * @param variant      the variant of the pipeline
254	     * @param session      the chat session
255	     * @param eventVariant the event variant if this function triggers a pipeline execution due to a specific event
256	     * @param post         the post the session is about
257	     */
258	    public void executeTutorSuggestionPipeline(String variant, IrisTutorSuggestionSession session, Optional<String> eventVariant, Post post) {
259	        var course = post.getCoursePostingBelongsTo();
260	        if (course == null) {
261	            throw new IllegalStateException("Course is null for post " + post.getId());
262	        }
263	        // The post can be located in a channel that is linked to an exercise. If so, we pass the exercise details to the pipeline.
264	        Long exerciseId = null;
265	        if (post.getConversation() instanceof Channel channel && channel.getExercise() != null) {
266	            exerciseId = channel.getExercise().getId();
267	        }
268	        final Long associatedExerciseId = exerciseId;
269	        // @formatter:off
270	        executePipeline(
271	            "tutor-suggestion",
272	            variant,
273	            eventVariant,
274	            pyrisJobService.addTutorSuggestionJob(post.getId(), course.getId(), session.getId()),
275	            executionDto -> {
276	                var user = userRepository.findByIdElseThrow(session.getUserId());
277	                Optional<PyrisTextExerciseDTO> textExerciseDTO = Optional.empty();
278	                Optional<PyrisProgrammingExerciseDTO> programmingExerciseDTO = Optional.empty();
279	                if (associatedExerciseId != null) {
280	                    Exercise exercise = exerciseRepository.findByIdElseThrow(associatedExerciseId);
281	                    if (exercise instanceof ProgrammingExercise) {
282	                        var programmingExercise = programmingExerciseRepository.findByIdWithTemplateAndSolutionParticipationElseThrow(associatedExerciseId);
283	                        programmingExerciseDTO = Optional.of(pyrisDTOService.toPyrisProgrammingExerciseDTO(programmingExercise));
284	                    }
285	                    else if (exercise instanceof TextExercise textExercise) {
286	                        textExerciseDTO = Optional.of(PyrisTextExerciseDTO.of(textExercise));
287	                    }
288	                }
289	                return new PyrisTutorSuggestionPipelineExecutionDTO(
290	                    new PyrisCourseDTO(course),
291	                    Optional.ofNullable(associatedExerciseId).map(Long::intValue),
292	                    new PyrisPostDTO(post),
293	                    pyrisDTOService.toPyrisMessageDTOList(session.getMessages()),
294	                    new PyrisUserDTO(user),
295	                    textExerciseDTO,
296	                    programmingExerciseDTO,
297	                    executionDto.settings(),
