188	     * Navigates through the available suggestions.
189	     *
190	     * @param up if true, move to the next (newer) suggestion, otherwise to the previous (older) one
191	     */
192	    switchSuggestion(up: boolean): void {
193	        if (!this.suggestion || !this.suggestions) {
194	            return;
195	        }
196	        const currentIndex = this.suggestions.indexOf(this.suggestion);
197	        if (currentIndex === -1) {
198	            return;
199	        }
200	        const newIndex = up ? currentIndex + 1 : currentIndex - 1;
201	        if (newIndex < 0 || newIndex >= this.suggestions.length) {
202	            return;
203	        }
204	        this.suggestion = this.suggestions[newIndex];
205	        this.updateArrowDisabled(newIndex);
206	    }
