225	        if (!post || !post.answers || post.answers.length === 0) {
226	            return false;
227	        }
228	        if (!this.suggestions || this.suggestions.length === 0) {
229	            return false;
230	        }
231	        const lastSuggestion = this.suggestions[this.suggestions.length - 1];
232	        if (!lastSuggestion.sentAt) {
233	            return false;
234	        }
